function sendTelegram(text) {
  // 跑測試時不要真的騷擾教練（scripts/test_invoice_inbound_hook.js 會設這個環境變數）
  if (process.env.INVOICE_HOOK_TEST === '1') return;
  try {
    const cfg = JSON.parse(fs.readFileSync(OPENCLAW_CONFIG_PATH, 'utf-8'));
    const botToken = cfg && cfg.channels && cfg.channels.telegram
      && cfg.channels.telegram.accounts && cfg.channels.telegram.accounts.bot_main
      && cfg.channels.telegram.accounts.bot_main.botToken;
    if (!botToken) return;
    // 2026-08-25教練要求：跟小龍蝦(AI)自己講的話要分得清楚，統一加標籤
    const body = JSON.stringify({
      chat_id: COACH_TELEGRAM_CHAT_ID,
      text: '🤖【賈維斯自動通知】\n' + text,
      disable_notification: true, // 只是回執，不該把教練從睡夢中吵醒
    });
    const req = https.request({
      hostname: 'api.telegram.org',
      path: `/bot${botToken}/sendMessage`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
      timeout: 8000,
    });
    req.on('error', () => {});
    req.on('timeout', () => req.destroy());
    req.write(body);
    req.end();
  } catch (e) {}
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;

  try {
    // 2026-09-06教練回報連兩則誤報：每30分鐘自動心跳健檢(channel/chatId皆為
    // 'heartbeat'，sessionKey固定'agent:main:main')會把HEARTBEAT.md全文當context
    // 灌進來，其中「timeout/INVALID_API_KEY/網路類錯誤需自動調參」這句系統狀態
    // 說明文字，恰好符合手機發票條碼格式(斜線+7碼英數)，被誤判成真的發票資訊。
    // 心跳本來就不是教練在講話，這支hook只該處理教練/會員的真實訊息，直接排除。
    if (resolveChannel(event) === 'heartbeat' || resolveChatId(event) === 'heartbeat') return;

    const text = extractText(event);
    if (!text) return;

    // 2026-09-10第二次發作：channel/chatId的排除失效了，因為心跳事件從9/9晚上起
    // 不再標示channel='heartbeat'，而是偽裝成channel='telegram'/chatId=教練本人ID
    // (跟教練真的在Telegram打字完全無法區分)，繞過上面那道排除。連續14次(9/9 23:07
    // ~9/10 03:36)誤把HEARTBEAT.md內文當發票資訊存檔+發靜音通知，教練半夜看到亂碼
    // 訊息「同步、連續第、輪全綠...載具/INVALID」才發現。
    // channel/chatId是間接推論值，會隨系統版本改變格式；改成直接偵測這段文字本身
    // 是不是心跳排程注入的固定prompt模板，不管未來channel怎麼偽裝都攔得住。
    if (/^Read HEARTBEAT\.md if it exists/.test(text.trim())) return;

    if (!TRIGGER_KEYWORD_RE.test(text) && !TRIGGER_CARRIER_RE.test(text)) return;

    const bits = parseInvoiceBits(text);
    // 沒撈到任何可用資訊（只是閒聊提到「發票」兩個字）就不記，避免雜訊
    if (bits.carriers.length === 0 && bits.taxIds.length === 0) return;

    fs.mkdirSync(INBOX_DIR, { recursive: true });

    const entry = {
      ts: Date.now(),
      iso: new Date().toISOString(),
      taipei: new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19),
      channel: resolveChannel(event),
      chatId: resolveChatId(event),
      sessionKey: event.sessionKey || (event.context && event.context.sessionKey) || '',
      names: bits.names,
      carriers: bits.carriers,
      taxIds: bits.taxIds,
      companies: bits.companies,
      type: bits.type,
      reconciled: false, // 對帳腳本比對過知識檔後會標記
      raw: text.slice(0, 2000),
    };

    // 同步寫入：收到當下立刻落地，不等 agent turn 跑完（agent 就算 overflow 重啟也不會掉）
    fs.appendFileSync(monthFile(), JSON.stringify(entry) + '\n');

    // 立刻給教練一句回執，讓他當場知道「這筆有進系統」，不用事後再問「你記了沒」
    const parts = [];
    if (bits.names.length) parts.push(bits.names.join('、'));
    if (bits.carriers.length) parts.push('載具 ' + bits.carriers.join(' '));
    if (bits.taxIds.length) parts.push('統編 ' + bits.taxIds.join(' '));
    if (bits.companies.length) parts.push(bits.companies.join('、'));
    if (bits.type) parts.push(bits.type);
    sendTelegram('🧾 發票資訊已自動存檔（不靠對話記憶，掉不了）\n' + parts.join('｜')

